import * as zlib from 'zlib';
import * as crypto from 'crypto';
import { Readable, Transform } from 'stream';
import { pipeline } from 'stream/promises';

interface UploadManifest {
  algorithm: string;
  keyDerivation: 'pbkdf2' | 'scrypt';
  iterations: number;
  compressed: boolean;
  chunkSize: number;
  totalChunks: number;
}

class DecompressionGuard extends Transform {
  private bytesProcessed: number = 0;
  private readonly maxBytes: number;
  private readonly compressionRatio: number;
  private inputBytes: number = 0;

  constructor(maxOutputBytes: number, maxRatio: number) {
    super();
    this.maxBytes = maxOutputBytes;
    this.compressionRatio = maxRatio;
  }

  _transform(chunk: Buffer, _encoding: string, callback: Function) {
    this.bytesProcessed += chunk.length;
    this.inputBytes += chunk.length;

    if (this.bytesProcessed > this.maxBytes) {
      callback(new Error(`Decompression limit exceeded: ${this.bytesProcessed} > ${this.maxBytes}`));
      return;
    }

    callback(null, chunk);
  }

  getRatio(): number {
    return this.inputBytes > 0 ? this.bytesProcessed / this.inputBytes : 0;
  }
}

class CryptoProcessor {
  private readonly MAX_UPLOAD_SIZE = 10 * 1024 * 1024; // 10MB compressed input
  private readonly MAX_DECOMPRESSED_SIZE = 50 * 1024 * 1024; // 50MB output
  private readonly MAX_COMPRESSION_RATIO = 100;
  private readonly CHUNK_TIMEOUT_MS = 5000;

  async processEncryptedUpload(
    encryptedPayload: Buffer,
    passphrase: string,
    manifest: UploadManifest
  ): Promise<Buffer> {
    this.validateManifest(manifest);

    if (encryptedPayload.length > this.MAX_UPLOAD_SIZE) {
      throw new Error(`Upload exceeds maximum size of ${this.MAX_UPLOAD_SIZE} bytes`);
    }

    const key = await this.deriveKey(passphrase, manifest);
    const decrypted = this.decryptPayload(encryptedPayload, key, manifest.algorithm);

    if (manifest.compressed) {
      return this.safeDecompress(decrypted, manifest);
    }

    return decrypted;
  }

  private validateManifest(manifest: UploadManifest): void {
    const validAlgorithms = ['aes-256-gcm', 'chacha20-poly1305'];
    if (!validAlgorithms.includes(manifest.algorithm)) {
      throw new Error(`Unsupported algorithm: ${manifest.algorithm}`);
    }
    if (manifest.iterations < 100000) {
      throw new Error('Insufficient key derivation iterations');
    }
    if (manifest.chunkSize < 1024 || manifest.chunkSize > 65536) {
      throw new Error('Invalid chunk size');
    }
    if (manifest.totalChunks < 1 || manifest.totalChunks > 10000) {
      throw new Error('Invalid chunk count');
    }
  }

  private async deriveKey(passphrase: string, manifest: UploadManifest): Promise<Buffer> {
    return new Promise((resolve, reject) => {
      const salt = crypto.randomBytes(32);
      if (manifest.keyDerivation === 'scrypt') {
        crypto.scrypt(passphrase, salt, 32, (err, key) => {
          if (err) reject(err);
          else resolve(key);
        });
      } else {
        crypto.pbkdf2(passphrase, salt, manifest.iterations, 32, 'sha512', (err, key) => {
          if (err) reject(err);
          else resolve(key);
        });
      }
    });
  }

  private decryptPayload(data: Buffer, key: Buffer, algorithm: string): Buffer {
    const iv = data.subarray(0, 12);
    const authTag = data.subarray(12, 28);
    const ciphertext = data.subarray(28);

    const decipher = crypto.createDecipheriv(algorithm, key, iv) as crypto.DecipherGCM;
    decipher.setAuthTag(authTag);

    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  }

  private async safeDecompress(data: Buffer, manifest: UploadManifest): Promise<Buffer> {
    const chunks: Buffer[] = [];
    let totalSize = 0;

    const processChunk = async (chunk: Buffer, index: number): Promise<Buffer> => {
      const guard = new DecompressionGuard(
        this.MAX_DECOMPRESSED_SIZE,
        this.MAX_COMPRESSION_RATIO
      );

      const inflater = zlib.createInflate({
        maxOutputLength: this.computeChunkLimit(manifest, index)
      });

      const outputChunks: Buffer[] = [];

      return new Promise((resolve, reject) => {
        const timeout = setTimeout(() => {
          inflater.destroy();
          reject(new Error('Chunk decompression timeout'));
        }, this.CHUNK_TIMEOUT_MS);

        inflater.on('data', (decompressed: Buffer) => {
          outputChunks.push(decompressed);
        });

        inflater.on('end', () => {
          clearTimeout(timeout);
          resolve(Buffer.concat(outputChunks));
        });

        inflater.on('error', (err) => {
          clearTimeout(timeout);
          reject(err);
        });

        inflater.write(chunk);
        inflater.end();
      });
    };

    for (let i = 0; i < manifest.totalChunks && i * manifest.chunkSize < data.length; i++) {
      const start = i * manifest.chunkSize;
      const end = Math.min(start + manifest.chunkSize, data.length);
      const chunk = data.subarray(start, end);

      const decompressed = await processChunk(chunk, i);
      totalSize += decompressed.length;

      if (totalSize > this.MAX_DECOMPRESSED_SIZE) {
        throw new Error('Total decompressed size exceeds limit');
      }

      chunks.push(decompressed);
    }

    return Buffer.concat(chunks);
  }

  private computeChunkLimit(manifest: UploadManifest, chunkIndex: number): number {
    // Per-chunk limit based on remaining budget
    // BUG: integer overflow when totalChunks is large - maxOutputLength becomes
    // effectively unlimited because Node's zlib treats values > 2^31-1 as no limit
    const perChunkBudget = Math.ceil(
      (this.MAX_DECOMPRESSED_SIZE * manifest.totalChunks) / (manifest.totalChunks - chunkIndex)
    );
    return perChunkBudget;
  }
}

export { CryptoProcessor, DecompressionGuard, UploadManifest };
